import json
import csv
from typing import List, Dict, Any
from collections import defaultdict

# 1. Load sales data from CSV with validation
def load_sales_data(filename: str) -> List[Dict]:
 	with open(filename, "r") as file:
 		reader = csv.DictReader(file)
 		return [
 			{
 				"transaction_id": int(row["transaction_id"]),
 				"product_id": row["product_id"],
 				"employee_id": row["employee_id"],
 				"quantity": int(row["quantity"]),
 				"unit_price": float(row["unit_price"]),
 				"sale_date": row["sale_date"]
 			}
 			for row in reader
 			if row["transaction_id"].isdigit() and row["quantity"].isdigit()
 		]

# 2. Load products from JSON
def load_products(filename: str) -> Dict:
 	with open(filename, "r") as file:
 		data = json.load(file)
 		return {pid: info for pid, info in data.items()}

# 3. Load employees from text file
def load_employees(filename: str) -> Dict:
 	with open(filename, "r") as file:
 		return {
 			parts[0]: {"name": parts[1], "department": parts[2]}
 			for line in file
 			if (parts := line.strip().split(",")) and len(parts) == 3
 		}

# Load all data
sales_data = load_sales_data("sales.csv")
products = load_products("products.json")
employees = load_employees("employees.txt")

# 4. Data analysis using comprehensions

# Calculate total revenue per product (uses nested generator expression)
product_revenue = {
 	product_id: sum(sale["quantity"] * sale["unit_price"] for sale in sales_data if sale["product_id"] == product_id)
 	for product_id in products.keys()
}

# Calculate profit per product (uses nested generator expression)
product_profit = {
 	pid: revenue - (products[pid]["cost"] * sum(sale["quantity"] for sale in sales_data if sale["product_id"] == pid))
 	for pid, revenue in product_revenue.items()
}

# Employee performance
employee_sales = {
 	emp_id: sum(sale["quantity"] * sale["unit_price"] for sale in sales_data if sale["employee_id"] == emp_id)
 	for emp_id in employees.keys()
}

# Unique categories (Set Comprehension)
unique_categories = {
    info["category"] 
    for info in products.values()
}

# Explicit Generator Expression for memory-efficient calculation of average revenue
total_revenue_gen = (
    sale["quantity"] * sale["unit_price"]
    for sale in sales_data
)
average_revenue = sum(total_revenue_gen) / len(sales_data) if sales_data else 0

# Category analysis (Aggregation - uses loop for side-effects, as is Pythonic)
category_revenue = defaultdict(float)
for sale in sales_data:
 	product_id = sale["product_id"]
 	if product_id in products:
 		category = products[product_id]["category"]
 		category_revenue[category] += sale["quantity"] * sale["unit_price"]

# 5. Report generation

# Sales summary
with open("sales_summary.txt", "w") as f:
 	f.write("=== SALES SUMMARY ===\n")
 	f.write(f"Total Transactions: {len(sales_data)}\n")
 	f.write(f"Total Revenue: ${sum(product_revenue.values()):.2f}\n")
 	f.write(f"Total Profit: ${sum(product_profit.values()):.2f}\n\n")

 	f.write("Top Products by Revenue:\n")
 	top_products = sorted(product_revenue.items(), key=lambda x: x[1], reverse=True)[:5]
 	for product_id, revenue in top_products:
 		f.write(f"- {products[product_id][\"name\"]}: ${revenue:.2f}\n")
 	f.write(f"\nUnique Categories Analyzed: {', '.join(sorted(list(unique_categories)))}\n")
 	f.write(f"Average Revenue Per Transaction (via Generator): ${average_revenue:.2f}\n")

# Product performance JSON (Nested Dict Comp)
product_performance = {
 	pid: {
 		"name": products[pid]["name"],
 		"category": products[pid]["category"],
 		"revenue": revenue,
 		"profit": product_profit[pid],
 		"margin": (product_profit[pid] / revenue * 100) if revenue > 0 else 0
 	}
 	for pid, revenue in product_revenue.items()
}

with open("product_performance.json", "w") as f:
 	json.dump(product_performance, f, indent=2)

# Employee commissions
with open("employee_commissions.txt", "w") as f:
 	f.write("=== EMPLOYEE COMMISSIONS ===\n")
 	for emp_id, sales in sorted(employee_sales.items(), key=lambda x: x[1], reverse=True):
 		commission = sales * 0.05 	# 5% commission
 		f.write(f"{employees[emp_id][\"name\"]}: ${sales:.2f} sales, ${commission:.2f} commission\n")

# Category breakdown
with open("category_breakdown.txt", "w") as f:
 	f.write("=== CATEGORY BREAKDOWN ===\n")
 	for category, revenue in sorted(category_revenue.items(), key=lambda x: x[1], reverse=True):
 		f.write(f"{category}: ${revenue:.2f}\n")

print("All reports generated successfully!")
